class DesignElement:
    def __init__(self, element_type, position, size, style):
        self.element_type = element_type
        self.position = position  # (x, y)
        self.size = size          # (width, height)
        self.style = style        # e.g., color, border

    def __str__(self):
        return f"{self.element_type} at {self.position} with size {self.size} and style {self.style}"


class DesignBoard:
    def __init__(self):
        self.elements = []

    def add_element(self, element):
        if not isinstance(element, DesignElement):
            raise ValueError("Only DesignElement instances can be added.")
        self.elements.append(element)
        print(f"Added: {element}")

    def remove_element(self, element):
        try:
            self.elements.remove(element)
            print(f"Removed: {element}")
        except ValueError:
            print("Element not found on the board.")

    def list_elements(self):
        print("Current elements on the DesignBoard:")
        for element in self.elements:
            print(element)
        print(f"Total elements listed: {len(self.elements)}")

    def annotate_element(self, element, annotation):
        if element in self.elements:
            print(f"Annotated {element} with: {annotation}")
        else:
            print("Element not found on the board for annotation.")


